    "                    hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                }\n"
    "                hm[mlen >> 2] |= ((uint)0x80u) << ((3 - (mlen & 3)) * 8);\n"
    "                hm[14] = 0;\n"
    "                hm[15] = (uint)(64 + mlen) * 8u;\n"
    "                sha256_block(&istate[0], hm);\n"
    "            } else {\n"
    "                int copy1 = (mlen < 64) ? mlen : 64;\n"
    "                for (int i = 0; i < 16; i++) hm[i] = 0;\n"
    "                for (int i = 0; i < copy1; i++) {\n"
    "                    uint v = (uint)data[i];\n"
    "                    hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                }\n"
    "                if (mlen < 64)\n"
    "                    hm[mlen >> 2] |= ((uint)0x80u) << ((3 - (mlen & 3)) * 8);\n"
    "                sha256_block(&istate[0], hm);\n"
    "                int rem = mlen - 64;\n"
    "                for (int i = 0; i < 16; i++) hm[i] = 0;\n"
    "                if (rem > 0) {\n"
    "                    for (int i = 0; i < rem; i++) {\n"
    "                        uint v = (uint)data[64 + i];\n"
    "                        hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                    }\n"
    "                }\n"
    "                if (mlen >= 64) {\n"
    "                    int p = (rem > 0) ? rem : 0;\n"
    "                    hm[p >> 2] |= ((uint)0x80u) << ((3 - (p & 3)) * 8);\n"
    "                }\n"
    "                hm[14] = 0;\n"
    "                hm[15] = (uint)(64 + mlen) * 8u;\n"
    "                sha256_block(&istate[0], hm);\n"
    "            }\n"
    "        } else {\n"
    "            /* Mode 6 KPASS: msg = salt_buf (global). Slab oracle line\n"
    "             * 213-229. */\n"
    "            if (mlen <= 55) {\n"
    "                for (int i = 0; i < 16; i++) hm[i] = 0;\n"
    "                for (int i = 0; i < mlen; i++) {\n"
    "                    uint v = (uint)salt_buf[i];\n"
    "                    hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                }\n"
    "                hm[mlen >> 2] |= ((uint)0x80u) << ((3 - (mlen & 3)) * 8);\n"
    "                hm[14] = 0;\n"
    "                hm[15] = (uint)(64 + mlen) * 8u;\n"
    "                sha256_block(&istate[0], hm);\n"
    "            } else {\n"
    "                int copy1 = (mlen < 64) ? mlen : 64;\n"
    "                for (int i = 0; i < 16; i++) hm[i] = 0;\n"
    "                for (int i = 0; i < copy1; i++) {\n"
    "                    uint v = (uint)salt_buf[i];\n"
    "                    hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                }\n"
    "                if (mlen < 64)\n"
    "                    hm[mlen >> 2] |= ((uint)0x80u) << ((3 - (mlen & 3)) * 8);\n"
    "                sha256_block(&istate[0], hm);\n"
    "                int rem = mlen - 64;\n"
    "                for (int i = 0; i < 16; i++) hm[i] = 0;\n"
    "                if (rem > 0) {\n"
    "                    for (int i = 0; i < rem; i++) {\n"
    "                        uint v = (uint)salt_buf[64 + i];\n"
    "                        hm[i >> 2] |= v << ((3 - (i & 3)) * 8);\n"
    "                    }\n"
    "                }\n"
    "                if (mlen >= 64) {\n"
    "                    int p = (rem > 0) ? rem : 0;\n"
    "                    hm[p >> 2] |= ((uint)0x80u) << ((3 - (p & 3)) * 8);\n"
    "                }\n"
    "                hm[14] = 0;\n"
    "                hm[15] = (uint)(64 + mlen) * 8u;\n"
    "                sha256_block(&istate[0], hm);\n"
    "            }\n"
    "        }\n"
    "\n"
    "        /* Step 3: outer = SHA256((key ^ opad) || inner_hash). istate[8]\n"
    "         * is BE; all 8 words copied directly into M[0..7]. M[8] =\n"
    "         * 0x80000000u (BE 0x80 at byte 32 = high octet of word 8).\n"
    "         * M[14]=0, M[15] = 768 bits (= 96 bytes * 8). Slab oracle line\n"
    "         * 117-133 / 232-246. */\n"
    "        uint opad_block[16];\n"
    "        for (int i = 0; i < 16; i++)\n"
    "            opad_block[i] = key_block[i] ^ 0x5c5c5c5cu;\n"
    "        for (int i = 0; i < 16; i++)\n"
    "            hm[i] = bswap32(opad_block[i]);\n"
    "\n"
    "        uint ostate[8] = { 0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u,\n"
    "                           0xa54ff53au, 0x510e527fu, 0x9b05688cu,\n"
    "                           0x1f83d9abu, 0x5be0cd19u };\n"
    "        sha256_block(&ostate[0], hm);\n"
    "\n"
    "        for (int i = 0; i < 8; i++) hm[i] = istate[i];\n"
    "        hm[8] = 0x80000000u;\n"
    "        for (int i = 9; i < 15; i++) hm[i] = 0;\n"
    "        hm[14] = 0;\n"
    "        hm[15] = (64u + 32u) * 8u;     /* 768 bits */\n"
    "        sha256_block(&ostate[0], hm);\n"
    "\n"
    "        /* Write final BE state into st.h[0..7] (template_digest_compare\n"
    "         * bswaps 4 leading words to LE for compact-table probe; emit_hit\n"
    "         * bswaps all 8 words for hits buffer). SHA256 emits the full\n"
    "         * 8-word digest — no truncation (unlike SHA224 which drops h[7]). */\n"
    "        for (int i = 0; i < 8; i++) st.h[i] = ostate[i];\n"
    "        return;\n"
    "    }\n"
    "\n"
    "    /* Process complete 64-byte blocks. Build M[] BIG-ENDIAN directly\n"
    "     * from bytes; salt bytes for p < slen, password bytes for p >= slen. */\n"
    "    while (total_len - pos >= HASH_BLOCK_BYTES) {\n"
    "        for (int j = 0; j < 16; j++) M[j] = 0;\n"
    "        for (int i = 0; i < HASH_BLOCK_BYTES; i++) {\n"
    "            int p = pos + i;\n"
    "            uchar c;\n"
    "            if (p < (int)slen) {\n"
    "                c = salt_buf[p];\n"
    "            } else {\n"
    "                c = data[p - (int)slen];\n"
    "            }\n"
    "            M[i >> 2] |= ((uint)c) << ((3 - (i & 3)) * 8);\n"
    "        }\n"
    "        sha256_block(&st.h[0], M);\n"
    "        pos += HASH_BLOCK_BYTES;\n"
    "    }\n"
    "\n"
    "    /* Build final block(s): tail bytes + 0x80 marker + zeros + 64-bit\n"
    "     * BE length. */\n"
    "    int rem = total_len - pos;  /* 0..63 */\n"
    "    for (int j = 0; j < 16; j++) M[j] = 0;\n"
    "    for (int i = 0; i < rem; i++) {\n"
    "        int p = pos + i;\n"
    "        uchar c;\n"
    "        if (p < (int)slen) {\n"
    "            c = salt_buf[p];\n"
    "        } else {\n"
    "            c = data[p - (int)slen];\n"
    "        }\n"
    "        M[i >> 2] |= ((uint)c) << ((3 - (i & 3)) * 8);\n"
    "    }\n"
    "    /* 0x80 padding marker, BE byte position. */\n"
    "    M[rem >> 2] |= ((uint)0x80u) << ((3 - (rem & 3)) * 8);\n"
    "\n"
    "    if (rem < 56) {\n"
    "        /* Length fits in this block. SHA-family BE: M[14] = high 32\n"
    "         * bits of bit count, M[15] = low 32 bits. For total_len < 2^29\n"
    "         * bytes (always true for our wordlist+salt inputs), high 32\n"
    "         * bits = 0. */\n"
    "        M[14] = 0;\n"
    "        M[15] = (uint)((uint)total_len * 8u);\n"
    "        sha256_block(&st.h[0], M);\n"
    "    } else {\n"
    "        /* Need one extra padding-only block to hold the length. */\n"
    "        sha256_block(&st.h[0], M);\n"
    "        for (int j = 0; j < 16; j++) M[j] = 0;\n"
    "        M[14] = 0;\n"
    "        M[15] = (uint)((uint)total_len * 8u);\n"
    "        sha256_block(&st.h[0], M);\n"
    "    }\n"
    "}\n"
    "\n"
    "/* template_iterate: -i loop step. Re-encode the 28-byte digest as 56-byte\n"
    " * lowercase hex ASCII and rehash with fresh SHA224 IV. lowercase hex of prior 56-char digest re-SHA224'd with FRESH IV (no salt re-application). Lines 30482-30484: prmd5(curin.h, newbuf, 56); mysha224(newbuf, 56, ...). Same compress as SHA256 but output is 28 bytes (vs 32) and iter input is 56 chars (vs 64) — the 56-char input fits in block 1 with 0x80 marker at M[14], length 448 in block 2.\n"
    " *\n"
    " *   - 7 state words -> 14 BE-encoded hex M[] words (2 words per state\n"
    " *     word, 4 hex chars each = 8 bytes per state word)\n"
    " *   - state reset to SHA224 IV; sha256_block on hex+pad block 1\n"
    " *   - Block 1 holds 56 bytes data + 0x80 pad marker at byte 56 (M[14]\n"
    " *     high byte) + zero padding through M[15]. Length is in block 2.\n"
    " *   - Block 2: M[0..14] = 0, M[15] = 56 * 8 = 448 bits.\n"
    " *   - sha256_block again. */\n"
    "static inline void template_iterate(thread template_state &st)\n"
    "{\n"
    "    uint M[16];\n"
    "    /* Encode 7 state words to 14 M[] words (56 hex chars). h[7] is NOT\n"
    "     * encoded — SHA224 truncates. */\n"
    "    for (int i = 0; i < 7; i++) {\n"
    "        uint s = st.h[i];\n"
    "        uint b0 = (s >> 24) & 0xff;\n"
    "        uint b1 = (s >> 16) & 0xff;\n"
    "        uint b2 = (s >> 8)  & 0xff;\n"
    "        uint b3 = s & 0xff;\n"
    "        uint hi0 = (b0 >> 4) & 0xf, lo0 = b0 & 0xf;\n"
    "        uint hi1 = (b1 >> 4) & 0xf, lo1 = b1 & 0xf;\n"
    "        uint hi2 = (b2 >> 4) & 0xf, lo2 = b2 & 0xf;\n"
    "        uint hi3 = (b3 >> 4) & 0xf, lo3 = b3 & 0xf;\n"
    "        uint h0 = ((hi0 + ((hi0 < 10) ? '0' : ('a' - 10))) << 8)\n"
    "                |  (lo0 + ((lo0 < 10) ? '0' : ('a' - 10)));\n"
    "        uint h1 = ((hi1 + ((hi1 < 10) ? '0' : ('a' - 10))) << 8)\n"
    "                |  (lo1 + ((lo1 < 10) ? '0' : ('a' - 10)));\n"
    "        uint h2 = ((hi2 + ((hi2 < 10) ? '0' : ('a' - 10))) << 8)\n"
    "                |  (lo2 + ((lo2 < 10) ? '0' : ('a' - 10)));\n"
    "        uint h3 = ((hi3 + ((hi3 < 10) ? '0' : ('a' - 10))) << 8)\n"
    "                |  (lo3 + ((lo3 < 10) ? '0' : ('a' - 10)));\n"
    "        M[i * 2]     = (h0 << 16) | h1;\n"
    "        M[i * 2 + 1] = (h2 << 16) | h3;\n"
    "    }\n"
    "    /* Block 1 tail: 0x80 marker at byte 56 (M[14] high byte), bytes 57-63\n"
    "     * zero. M[15] is zero (length in block 2). */\n"
    "    M[14] = 0x80000000u;\n"
    "    M[15] = 0u;\n"
    "\n"
    "    /* Reset state to SHA224 IV; absorb the 56-byte hex + pad block. */\n"
    "    st.h[0] = 0xc1059ed8u; st.h[1] = 0x367cd507u;\n"
    "    st.h[2] = 0x3070dd17u; st.h[3] = 0xf70e5939u;\n"
    "    st.h[4] = 0xffc00b31u; st.h[5] = 0x68581511u;\n"
    "    st.h[6] = 0x64f98fa7u; st.h[7] = 0xbefa4fa4u;\n"
    "    sha256_block(&st.h[0], M);\n"
    "\n"
    "    /* Second block: pad zeros + length only. SHA224 hex (56 bytes)\n"
    "     * already had its 0x80 marker in block 1; block 2 holds the 64-bit\n"
    "     * BE length in M[14..15]. M[14] high 32 = 0 (56*8 < 2^32);\n"
    "     * M[15] = 56 * 8 = 448 bits. */\n"
    "    for (int j = 0; j < 16; j++) M[j] = 0u;\n"
    "    M[15] = 56u * 8u;       /* 56 hex chars = 448 bits */\n"
    "    sha256_block(&st.h[0], M);\n"
    "}\n"
    "\n"
    "/* template_digest_compare: probe the compact table with the final digest.\n"
    " * SHA224 state is BE; bswap leading 4 words to LE (host's compact_table\n"
    " * key encoding). The remaining state words (h[4..6]) are NOT used by the\n"
    " * compact-table probe — only by EMIT_HIT_7 below. h[7] is ignored. */\n"
    "static inline int template_digest_compare(thread const template_state &st,\n"
    "                                device const uint *compact_fp,\n"
    "                                device const uint *compact_idx,\n"
    "                                ulong compact_mask,\n"
    "                                uint max_probe,\n"
    "                                uint hash_data_count,\n"
    "                                device const uchar *hash_data_buf,\n"
    "                                device const ulong *hash_data_off,\n"
    "                                device const ulong *overflow_keys,\n"
    "                                device const uchar *overflow_hashes,\n"
    "                                device const uint *overflow_offsets,\n"
    "                                uint overflow_count,\n"
    "                                thread uint *out_idx)\n"
    "{\n"
    "    uint h0 = bswap32(st.h[0]);\n"
    "    uint h1 = bswap32(st.h[1]);\n"
    "    uint h2 = bswap32(st.h[2]);\n"
    "    uint h3 = bswap32(st.h[3]);\n"
    "    return probe_compact_idx(\n"
    "        h0, h1, h2, h3,\n"
    "        compact_fp, compact_idx,\n"
    "        compact_mask, max_probe, hash_data_count,\n"
    "        hash_data_buf, hash_data_off,\n"
    "        overflow_keys, overflow_hashes, overflow_offsets, overflow_count,\n"
    "        out_idx);\n"
    "}\n"
    "\n"
    "\n"
    "/* B3 dedup+overflow-aware variant. */\n"
    "#define template_emit_hit_or_overflow(hits, hit_count, max_hits, st, widx, sidx, iter, \\\n"
    "                                      hashes_shown, matched_idx, dedup_mask, \\\n"
    "                                      ovr_set, ovr_gid, lane_gid) \\\n"
    "    do { \\\n"
    "        uint _h[7]; \\\n"
    "        _h[0] = bswap32((st).h[0]); \\\n"
    "        _h[1] = bswap32((st).h[1]); \\\n"
    "        _h[2] = bswap32((st).h[2]); \\\n"
    "        _h[3] = bswap32((st).h[3]); \\\n"
    "        _h[4] = bswap32((st).h[4]); \\\n"
    "        _h[5] = bswap32((st).h[5]); \\\n"
    "        _h[6] = bswap32((st).h[6]); \\\n"
    "        EMIT_HIT_7_DEDUP_OR_OVERFLOW((hits), (hit_count), (max_hits), \\\n"
    "                   (widx), (sidx), (iter), _h, \\\n"
    "                   (hashes_shown), (matched_idx), (dedup_mask), \\\n"
    "                   (ovr_set), (ovr_gid), (lane_gid)); \\\n"
    "    } while (0)\n"
;
